<?php require_once '../includes/auth.php';requireLogin();requireTenantContext();$tenantId=getCurrentTenantId();$rows=[];$q=$conn->query("SHOW TABLES LIKE 'active_sessions'");if($q&&$q->num_rows){$sql="SELECT * FROM active_sessions";if($tenantId)$sql.=" WHERE tenant_id=".(int)$tenantId;$sql.=" ORDER BY id DESC LIMIT 200";$r=$conn->query($sql);if($r)while($x=$r->fetch_assoc())$rows[]=$x;}
$pageTitle='Hotspot Sessions';require_once '../includes/header.php';?><div class="dashboard-card"><h2>Hotspot Sessions</h2><p><?=e(count($rows))?> active session record(s).</p><?php if($rows):?><div class="table-responsive"><table><thead><tr><?php foreach(array_keys($rows[0]) as $k):?><th><?=e(ucwords(str_replace('_',' ',$k)))?></th><?php endforeach;?></tr></thead><tbody><?php foreach($rows as $x):?><tr><?php foreach($x as $v):?><td><?=e($v)?></td><?php endforeach;?></tr><?php endforeach;?></tbody></table></div><?php endif;?></div><?php require_once '../includes/footer.php';?>